/*
 * BÀI TEST: 17.1-xapian-parallel-delete
 * MÔ TẢ   : Tạo 10 documents mẫu trong Xapian DB, sau đó gửi 10 giao dịch đồng thời từ 10 ví để xóa 10 document này.
 * KỲ VỌNG : - Block-STM xử lý 10 giao dịch xóa song song không bị xung đột hay lỗi abort.
 *           - Lệnh tìm kiếm (querySearch) sau khi xóa trả về 0 document.
 *           - Lệnh đọc dữ liệu (getDataDocument) của từng document đã xóa trả về rỗng (0 bytes).
 */
package main

import (
	"tool-test/test-simple/test-rpc/test-blockstm/config"
	"context"
	"crypto/ecdsa"
	"fmt"
	"log"
	"math/big"
	"os"
	"strings"
	"sync"
	"time"

	"github.com/ethereum/go-ethereum/accounts/abi"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/types"
	"github.com/ethereum/go-ethereum/crypto"
	"github.com/ethereum/go-ethereum/ethclient"
)

const abiJSON = `[{"inputs":[],"stateMutability":"nonpayable","type":"constructor"},{"anonymous":false,"inputs":[{"indexed":false,"internalType":"uint256","name":"index","type":"uint256"},{"indexed":false,"internalType":"uint256","name":"docId","type":"uint256"}],"name":"DocumentCreated","type":"event"},{"anonymous":false,"inputs":[{"indexed":true,"internalType":"address","name":"wallet","type":"address"},{"indexed":false,"internalType":"uint256","name":"index","type":"uint256"},{"indexed":false,"internalType":"uint256","name":"docId","type":"uint256"}],"name":"DocumentDeleted","type":"event"},{"anonymous":false,"inputs":[{"indexed":false,"internalType":"uint256","name":"totalFound","type":"uint256"}],"name":"SearchExecuted","type":"event"},{"inputs":[{"internalType":"uint256","name":"index","type":"uint256"}],"name":"deleteDoc","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"","type":"uint256"}],"name":"docIds","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"index","type":"uint256"}],"name":"getDocData","outputs":[{"internalType":"bytes","name":"","type":"bytes"}],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"initDocs","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"string","name":"query","type":"string"}],"name":"searchDocs","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"nonpayable","type":"function"}]`

const bytecodeHex = ""


func main() {
	fmt.Println("==========================================================")
	fmt.Println("BÀI TEST: 17.1-xapian-parallel-delete")
	fmt.Println("==========================================================")
	fmt.Println("📖 MÔ TẢ   : Tạo 10 documents mẫu, sau đó gửi 10 tx deleteDocument đồng thời.")
	fmt.Println("🎯 KỲ VỌNG : Giao dịch không bị abort, searchDocument sẽ thấy 0 document, getDataDocument rỗng.")
	fmt.Println("==========================================================")

	configPath := "../config.json"
	if len(os.Args) > 1 {
		configPath = os.Args[1]
	}

	cfg, err := config.LoadConfig(configPath)
	if err != nil {
		log.Fatalf("❌ Lỗi load config: %v", err)
	}

	client, err := ethclient.Dial(cfg.RPCUrl)
	if err != nil {
		log.Fatalf("❌ Lỗi kết nối RPC: %v", err)
	}

	contractABI, err := abi.JSON(strings.NewReader(abiJSON))
	if err != nil {
		log.Fatalf("❌ Lỗi parse ABI: %v", err)
	}
	bytecode, err := common.ParseHexOrString(bytecodeHex)
	if err != nil {
		log.Fatalf("❌ Lỗi decode bytecode: %v", err)
	}

	if len(cfg.PrivateKeys) < 10 {
		log.Fatalf("❌ Cần ít nhất 10 private keys cho bài test này")
	}
	testKeys := cfg.PrivateKeys[:10]

	pk0, _ := crypto.HexToECDSA(testKeys[0])
	from0 := crypto.PubkeyToAddress(*pk0.Public().(*ecdsa.PublicKey))

	fmt.Println("🚀 Deploying ParallelDeleteXapian contract with Account 0...")
	contractAddr, err := deployContract(client, pk0, cfg.ChainID, from0, bytecode)
	if err != nil {
		log.Fatalf("❌ Deploy thất bại: %v", err)
	}
	fmt.Printf("📌 Contract deployed at: %s\n\n", contractAddr.Hex())

	// Bước 1: Khởi tạo 10 documents mẫu
	fmt.Println("📦 Khởi tạo 10 documents mẫu ban đầu bằng Account 0 (initDocs)...")
	initHash, err := sendTx(client, pk0, cfg.ChainID, from0, contractAddr, contractABI, "initDocs")
	if err != nil {
		log.Fatalf("❌ Gửi initDocs thất bại: %v", err)
	}
	initReceipt, err := waitReceipt(client, initHash)
	if err != nil || initReceipt.Status != 1 {
		log.Fatalf("❌ initDocs bị revert hoặc lỗi receipt: %v", err)
	}
	fmt.Println("✅ Đã tạo thành công 10 documents mẫu trong Xapian DB.")

	// Kiểm tra ban đầu: searchDocs phải tìm thấy 10 docs
	fmt.Println("\n🔍 Kiểm tra trước khi xóa: searchDocs('delete_target_doc')...")
	preSearchHash, err := sendTx(client, pk0, cfg.ChainID, from0, contractAddr, contractABI, "searchDocs", "delete_target_doc")
	if err != nil {
		log.Fatalf("❌ Lỗi gửi pre-search: %v", err)
	}
	preSearchReceipt, err := waitReceipt(client, preSearchHash)
	if err != nil || preSearchReceipt.Status != 1 {
		log.Fatalf("❌ Pre-search bị lỗi receipt: %v", err)
	}
	preTotalFound := getSearchEventData(preSearchReceipt, contractABI)
	fmt.Printf("📊 Số document tìm thấy trước khi xóa: %d (Kỳ vọng: 10)\n\n", preTotalFound)

	// Bước 2: Gửi 10 giao dịch xóa đồng thời từ 10 ví khác nhau
	var wg sync.WaitGroup
	var errs []error
	var errsMu sync.Mutex

	fmt.Printf("🔥 Gửi 10 giao dịch xóa đồng thời (deleteDoc 0..9 từ 10 ví khác nhau)...\n")
	start := time.Now()

	txHashes := make([]common.Hash, 10)

	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(idx int, pKeyHex string) {
			defer wg.Done()

			pk, _ := crypto.HexToECDSA(pKeyHex)
			from := crypto.PubkeyToAddress(*pk.Public().(*ecdsa.PublicKey))

			hash, txErr := sendTx(client, pk, cfg.ChainID, from, contractAddr, contractABI, "deleteDoc", big.NewInt(int64(idx)))
			if txErr != nil {
				errsMu.Lock()
				errs = append(errs, fmt.Errorf("lỗi send tx deleteDoc(%d) từ wallet %d: %v", idx, idx, txErr))
				errsMu.Unlock()
				return
			}
			txHashes[idx] = hash
		}(i, testKeys[i])
	}

	wg.Wait()

	if len(errs) > 0 {
		fmt.Println("❌ Một số giao dịch gửi thất bại:")
		for _, e := range errs {
			fmt.Println("  -", e)
		}
	}

	fmt.Println("⏳ Chờ các giao dịch deleteDoc được confirm...")
	deleteSuccessCount := 0
	for i, hash := range txHashes {
		if hash == (common.Hash{}) {
			continue
		}
		receipt, err := waitReceipt(client, hash)
		if err != nil {
			fmt.Printf("❌ Wallet %d chờ receipt thất bại: %v\n", i, err)
		} else if receipt.Status != 1 {
			fmt.Printf("❌ Wallet %d Tx deleteDoc(%d) bị revert!\n", i, i)
		} else {
			fmt.Printf("✅ Wallet %d Tx deleteDoc(%d) confirmed (Block: %d)\n", i, i, receipt.BlockNumber.Uint64())
			deleteSuccessCount++
		}
	}

	elapsed := time.Since(start)

	// Bước 3: Kiểm tra sau khi xóa
	fmt.Println("\n🔍 Thực hiện searchDocs sau khi xóa...")
	postSearchHash, err := sendTx(client, pk0, cfg.ChainID, from0, contractAddr, contractABI, "searchDocs", "delete_target_doc")
	if err != nil {
		log.Fatalf("❌ Lỗi gửi post-search: %v", err)
	}
	postSearchReceipt, err := waitReceipt(client, postSearchHash)
	if err != nil || postSearchReceipt.Status != 1 {
		log.Fatalf("❌ post-search bị lỗi receipt!")
	}
	postTotalFound := getSearchEventData(postSearchReceipt, contractABI)

	// Bước 4: Kiểm tra đọc trực tiếp dữ liệu từng doc đã xóa
	fmt.Println("\n📄 Kiểm tra getDocData cho từng document đã xóa...")
	emptyDocCount := 0
	for i := 0; i < 10; i++ {
		dataHash, err := sendTx(client, pk0, cfg.ChainID, from0, contractAddr, contractABI, "getDocData", big.NewInt(int64(i)))
		if err != nil {
			fmt.Printf("⚠️ Lỗi gọi getDocData(%d): %v\n", i, err)
			continue
		}
		dataReceipt, err := waitReceipt(client, dataHash)
		if err == nil && dataReceipt.Status == 1 {
			emptyDocCount++
		}
	}

	fmt.Println("\n==========================================================")
	fmt.Println("📊 KẾT QUẢ TỔNG HỢP:")
	fmt.Printf("- Thời gian gửi & confirm: %v\n", elapsed)
	fmt.Printf("- Số tx deleteDoc thành công: %d / 10\n", deleteSuccessCount)
	fmt.Printf("- Số document tìm thấy trước khi xóa: %d (Kỳ vọng: 10)\n", preTotalFound)
	fmt.Printf("- Số document tìm thấy sau khi xóa: %d (Kỳ vọng: 0)\n", postTotalFound)
	fmt.Printf("- Số document xác nhận đã xóa sạch data: %d / 10\n", emptyDocCount)

	if deleteSuccessCount == 10 && preTotalFound == 10 && postTotalFound == 0 {
		fmt.Println("🎉 TEST PASSED: BlockSTM xử lý song song DELETE_DOCUMENT trên Xapian DB hoàn hảo!")
	} else {
		fmt.Printf("⚠️ TEST FAILED: Kết quả không đúng kỳ vọng.\n")
	}
	fmt.Println("==========================================================")
}

// Helpers

func deployContract(client *ethclient.Client, pk *ecdsa.PrivateKey, chainID int64, from common.Address, bytecode []byte) (*common.Address, error) {
	nonce, err := client.PendingNonceAt(context.Background(), from)
	if err != nil {
		return nil, err
	}
	gasPrice, _ := client.SuggestGasPrice(context.Background())
	if gasPrice == nil || gasPrice.Sign() == 0 {
		gasPrice = big.NewInt(1000000000)
	}

	gasLimit := uint64(5_000_000)

	tx := types.NewContractCreation(nonce, big.NewInt(0), gasLimit, gasPrice, bytecode)
	signedTx, err := types.SignTx(tx, types.NewEIP155Signer(big.NewInt(chainID)), pk)
	if err != nil {
		return nil, err
	}
	if err := client.SendTransaction(context.Background(), signedTx); err != nil {
		return nil, err
	}
	receipt, err := waitReceipt(client, signedTx.Hash())
	if err != nil {
		return nil, err
	}
	if receipt.Status != 1 {
		return nil, fmt.Errorf("deploy reverted")
	}
	return &receipt.ContractAddress, nil
}

func sendTx(client *ethclient.Client, pk *ecdsa.PrivateKey, chainID int64, from common.Address, to *common.Address, parsedABI abi.ABI, method string, args ...interface{}) (common.Hash, error) {
	data, err := parsedABI.Pack(method, args...)
	if err != nil {
		return common.Hash{}, err
	}
	nonce, err := client.PendingNonceAt(context.Background(), from)
	if err != nil {
		return common.Hash{}, err
	}
	gasPrice, _ := client.SuggestGasPrice(context.Background())
	if gasPrice == nil || gasPrice.Sign() == 0 {
		gasPrice = big.NewInt(1000000000)
	}

	gasLimit := uint64(3_000_000)

	tx := types.NewTransaction(nonce, *to, big.NewInt(0), gasLimit, gasPrice, data)
	signedTx, err := types.SignTx(tx, types.NewEIP155Signer(big.NewInt(chainID)), pk)
	if err != nil {
		return common.Hash{}, err
	}
	if err := client.SendTransaction(context.Background(), signedTx); err != nil {
		return common.Hash{}, err
	}
	return signedTx.Hash(), nil
}

func waitReceipt(client *ethclient.Client, txHash common.Hash) (*types.Receipt, error) {
	timeoutStart := time.Now()
	for {
		if time.Since(timeoutStart) > 60*time.Second {
			fmt.Println("❌ Timeout waiting for receipt")
			os.Exit(1)
		}
		receipt, err := client.TransactionReceipt(context.Background(), txHash)

		if err != nil && !strings.Contains(err.Error(), "not found") {
			fmt.Printf("Lỗi kết nối RPC: %v\n", err)
			os.Exit(1)
		}
		if err == nil && receipt != nil && receipt.BlockNumber != nil && receipt.BlockNumber.Uint64() > 0 {
			return receipt, nil
		}
		if err != nil && err.Error() != "not found" {
			return nil, err
		}
		time.Sleep(100 * time.Millisecond)
	}
}

func getSearchEventData(receipt *types.Receipt, parsedABI abi.ABI) uint64 {
	for _, log := range receipt.Logs {
		event, err := parsedABI.EventByID(log.Topics[0])
		if err == nil && event.Name == "SearchExecuted" {
			data, err := event.Inputs.Unpack(log.Data)
			if err == nil && len(data) > 0 {
				if total, ok := data[0].(*big.Int); ok {
					return total.Uint64()
				}
			}
		}
	}
	return 0
}
